// Generic Portuguese intentionally stays unmatched so pt-PT is never mistaken for pt-BR.
function steamLangToLang(raw) {
    const v = (raw ?? "").trim().toLowerCase();
    if (v === "en" || v.startsWith("english"))
        return "en";
    if (v === "it" || v.startsWith("italian"))
        return "it";
    if (v === "de" || v.startsWith("german"))
        return "de";
    if (v === "pt-br" || v === "brazilian" || v === "brazilian portuguese")
        return "pt-BR";
    return "es";
}

async function readSteamLanguage() {
    try {
        const settings = SteamClient?.Settings;
        if (typeof settings?.GetCurrentLanguage !== "function")
            return null;
        const lang = await settings.GetCurrentLanguage();
        return typeof lang === "string" ? lang : null;
    }
    catch {
        return null;
    }
}

